import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-109: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short109', durationInSeconds: 32.1, fps: 30, width: 1080, height: 1920 };


const B1 = secToFrame(3.3);
const B2 = secToFrame(5.3);
const B3 = secToFrame(13.2);
const B4 = secToFrame(17.2);
const CTA = secToFrame(29.7);

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short109: React.FC = () => {
  const frame = useCurrentFrame();
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={B1}>
        <CoverImage src="projects/short-109/cover.png" out={B1 - 10} />
        <HookTitle hold onDark kicker="OPENAI PRICING" lines={[{ text: 'ULTRAFAST' },{ text: 'COSTS 6X', accent: true }]} />
      </FadeOut>
      <FadeOut at={B2}>
        <ToolCard name="Sol: Standard" tagline="GPT-6.1 Sol list price." chip="$2 / $10" at={B1 + 4}>
          <Panel>
            <Line k="input /1M" v="$2.00" good />
            <Line k="output /1M" v="$10.00" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B3}>
        <ToolCard name="Ultrafast Sol" tagline="Same model, speed tier." chip="$12 / $60" at={B2 + 4} chipColor={COLORS.danger}>
          <Panel>
            <Line k="input /1M" v="$12.00" bad />
            <Line k="output /1M" v="$60.00" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B4}>
        <ToolCard name="Fast: the middle" tagline="Half-step up." chip="$4 / $20" at={B3 + 4} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="input /1M" v="$4.00" />
            <Line k="output /1M" v="$20.00" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="Astra Ultrafast" tagline="Flagship, same markup." chip="$60 / $300" at={B4 + 4} chipColor={COLORS.danger}>
          <Panel>
            <Line k="Standard out" v="$50" good />
            <Line k="Ultrafast out" v="$300" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-109/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="OPENAI PRICING" lines={[{ text: 'ULTRAFAST' },{ text: 'COSTS 6X', accent: true }]} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Two dollars, or twelve.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short109;
